def youngest(list_patches: List[ImagePatch]) -> str:
    """Returns the age of the youngest person in the list of ImagePatches."""
    ages = []
    for patch in list_patches:
        people_patches = patch.find("person")
        for person_patch in people_patches:
            age_str = person_patch.simple_query("How old is this person?")
            try:
                age = int(age_str.split()[0])
                ages.append(age)
            except ValueError:
                continue
    if not ages:
        return "No people found"
    return f"The youngest person is {min(ages)} years old."

